     1	import {createChatOrchestrator} from './chatOrchestrator.js';
     2	import type {OrchestratorHooks} from './chatOrchestrator.js';
     3	import type {AIProvider, MessageChunk} from '../types/ai.js';
     4	import type {ChatSession} from '../types/session.js';
     5	import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
     6	
     7	const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});
     8	
     9	const sessionWith = (content: string): ChatSession => ({
    10	  sessionId: 'test-session',
    11	  userId: 'user-1',
    12	  entries: [{role: 'user', content, timestamp: new Date().toISOString()}],
    13	});
    14	
    15	const rejectingWith = (reason: unknown): AIProvider => ({
    16	  // eslint-disable-next-line require-yield
    17	  async *sendMessage(): AsyncGenerator<MessageChunk> {
    18	    throw reason;
    19	  },
    20	  async generateStructured<T>(): Promise<T> {
    21	    return {} as T;
    22	  },
    23	});
    24	
    25	const turnOutcome = async (reason: unknown) => {
    26	  const callOrder: string[] = [];
    27	  let seenError: Error | undefined;
    28	  const hooks: OrchestratorHooks = {
    29	    onError: async (_session, error) => {
    30	      callOrder.push('onError');
    31	      seenError = error;
    32	    },
    33	    afterSession: async () => {
    34	      callOrder.push('afterSession');
    35	    },
    36	  };
    37	
    38	  const orchestrator = createChatOrchestrator(rejectingWith(reason), promptBuilder, undefined, {hooks});
    39	  const outcome = await orchestrator.processMessage(sessionWith('hello')).then(
    40	    value => ({rejected: false, reason: value as unknown}),
    41	    (thrown: unknown) => ({rejected: true, reason: thrown})
    42	  );
    43	
    44	  return {
    45	    outcome,
    46	    callOrder,
    47	    isError: seenError instanceof Error,
    48	    message: seenError?.message,
    49	  };
    50	};
    51	
    52	describe('ChatOrchestrator onError on non-Error rejections', () => {
    53	  it('calls onError with an Error carrying the thrown string and runs afterSession while rethrowing', async () => {
    54	    const result = await turnOutcome('string boom');
    55	
    56	    expect(result).toEqual({
    57	      outcome: {rejected: true, reason: 'string boom'},
    58	      callOrder: ['onError', 'afterSession'],
    59	      isError: true,
    60	      message: 'string boom',
    61	    });
    62	  });
    63	
    64	  it('calls onError with an Error carrying a readable message when the stream rejects with a plain object', async () => {
    65	    const reason = {code: 503, detail: 'upstream down'};
    66	
    67	    const result = await turnOutcome(reason);
    68	
    69	    expect({
    70	      outcome: result.outcome,
    71	      callOrder: result.callOrder,
    72	      isError: result.isError,
    73	      hasMessage: typeof result.message === 'string' && result.message.length > 0,
    74	    }).toEqual({
    75	      outcome: {rejected: true, reason},
    76	      callOrder: ['onError', 'afterSession'],
    77	      isError: true,
    78	      hasMessage: true,
    79	    });
    80	  });
    81	});
